CREATE TABLE IF NOT EXISTS factories (id TEXT NOT NULL PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, address TEXT, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS departments (id TEXT NOT NULL PRIMARY KEY, factoryId TEXT NOT NULL REFERENCES factories(id) ON DELETE CASCADE, code TEXT NOT NULL, name TEXT NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL, UNIQUE(factoryId, code));
CREATE TABLE IF NOT EXISTS department_members (id TEXT NOT NULL PRIMARY KEY, departmentId TEXT NOT NULL REFERENCES departments(id) ON DELETE CASCADE, userId TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, isHead BOOLEAN NOT NULL DEFAULT false, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(departmentId, userId));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT NOT NULL PRIMARY KEY, issueId TEXT NOT NULL REFERENCES quality_issues(id) ON DELETE CASCADE, userId TEXT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, oldStatus TEXT, newStatus TEXT, note TEXT, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id TEXT NOT NULL PRIMARY KEY, userId TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, issueId TEXT REFERENCES quality_issues(id) ON DELETE SET NULL, title TEXT NOT NULL, message TEXT NOT NULL, kind TEXT NOT NULL, isRead BOOLEAN NOT NULL DEFAULT false, readAt DATETIME, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
